/// <summary>
/// PaffH 28.08.25
/// </summary>
[ExtensionOf(formStr(smmContactPerson))]
final class NDXsmmContactPerson_frm_Extension
{
    public NDXBVSearchContract nDXBVSearchContract;

}

Method.Source:
/// <summary>
/// PaffH 28.08.25
/// get NDXBVSearchContract
/// </summary>
public void init()
{
    if (this.args() &&
        this.args().parmObject() is NDXBVSearchContract)
    {
        nDXBVSearchContract = this.args().parmObject() as NDXBVSearchContract;
    }
    next init();
}

/// <summary>
/// PaffH 01.09.25
/// set tab BV-Email visible
/// </summary>
public void updateControls()
{
    next updateControls();

    if (nDXBVSearchContract)
    {
        FormActionPaneTabControl faptc = this.design().controlName(formControlStr(smmContactPerson, NDXFormActionPaneTabBVEmailBoard));
        faptc.visible(true);
        FormButtonControl fbc = this.design().controlName(formControlStr(smmContactPerson, NDXFormButtonEMailfilterActivate));
        fbc.text(nDXBVSearchContract.filterFromContactPersonEmail(0, false));
        fbc = this.design().controlName(formControlStr(smmContactPerson, NDXFormButtonEMailfilterActivateLikePart01));
        fbc.text(nDXBVSearchContract.filterFromContactPersonEmail(1, false));
        fbc = this.design().controlName(formControlStr(smmContactPerson, NDXFormButtonEMailfilterActivateLikePart02));
        fbc.text(nDXBVSearchContract.filterFromContactPersonEmail(2, false));
        fbc = this.design().controlName(formControlStr(smmContactPerson, NDXFormButtonGetContact));
        fbc.enabled(nDXBVSearchContract.parmInEditMode());

    }
}

/// <summary>
/// PaffH 01.09.25
/// set filter range
/// </summary>
/// <param name = "_set">set filter</param>
/// <param name = "_part">int</param>
public void setFilterBVEmail(boolean _set = true, int _part = 0)
{
    if (!nDXBVSearchContract)
    {
        return;
    }
    QueryBuildRange range;
    QueryBuildDataSource qbds;
    JoinMode joinMode;

    qbds = SysQuery::findOrCreateDataSource(DirPerson_ds.query(), tableNum(LogisticsElectronicAddress), tableNum(DirPerson));
    range = SysQuery::findOrCreateRange(qbds, fieldNum(LogisticsElectronicAddress, Locator));
    if (_set)
    {
        joinMode = qbds.joinMode(JoinMode::InnerJoin);
        if (_part)
        {
            range.value(SysQuery::valueLike(nDXBVSearchContract.filterFromContactPersonEmail(_part, true)));
        }
        else
        {
            range.value(queryValue(nDXBVSearchContract.filterFromContactPersonEmail(_part, true)));
        }
    }
    else
    {
        joinMode = qbds.joinMode(JoinMode::OuterJoin);
        range.value(SysQuery::valueUnlimited());
    }
    ContactPerson_ds.executeQuery();
}
